#!/usr/bin/env python3
"""Compose the dossier's numbers from the three ensemble JSONs (regenerated by regen.sh)."""
import json, statistics, sys, pathlib

R = pathlib.Path(__file__).resolve().parent
P_PLANET_S = 11.86 * 3.156e7  # the planet's period in seconds (5.2 AU about a solar mass)
ORBIT_25AU_S = 3.95 * 3.156e7  # a belt orbit at 2.5 AU

rows = {n: [json.loads(l) for l in open(R / f"work/lyap_{n}.jsonl")] for n in ("control", "belt", "coorbital")}

P_PLANET = 7.600e13  # the planet's period in the integrator's time units: TAU * sep^{3/2}

def per_local_orbit_unused():
    pass
def lam_local(r, name):
    """lambda per local orbit (per planet period for the co-orbital ensemble)."""
    if name == "coorbital":
        return r["lam_pp"] * P_PLANET
    a = r["a_au"]
    ratio = (a / 5.2) ** 1.5  # P_local / P_planet
    return r["lam_pp"] * P_PLANET * ratio

out = {}
for name, rs in rows.items():
    lam = sorted(lam_local(r, name) for r in rs)
    n = len(lam)
    q = lambda f: lam[min(n - 1, int(f * (n - 1)))]
    out[name] = dict(
        n=n, gave_up=sum(r["gave_up"] for r in rs), sat=sum(r["sat"] for r in rs),
        p50=q(0.5), p90=q(0.9), p99=q(0.99), max=lam[-1],
        frac_gt_1e_2=sum(l > 1e-2 for l in lam) / n,
        frac_gt_1e_3=sum(l > 1e-3 for l in lam) / n,
        stretch_max=max(r["stretch"] for r in rs),
    )

print("== per local orbit ==")
for name, o in out.items():
    print(f"{name:10s} n={o['n']:3d} sat={o['sat']:3d} p50={o['p50']:9.3e} p90={o['p90']:9.3e} "
          f"p99={o['p99']:9.3e} max={o['max']:9.3e} frac>1e-2={o['frac_gt_1e_2']:.3f} frac>1e-3={o['frac_gt_1e_3']:.3f} stretch_max={o['stretch_max']:.1f}")

null = max(abs(out["control"]["p99"]), abs(out["control"]["max"]))
print(f"\nnull band (control |lambda| per local orbit): {null:.2e}, control stretch_max (bounded): {out['control']['stretch_max']:.1f}")

# P5: the budget composition. Even if EVERY body of a 1e9 belt sat at the belt's p99 rate:
lam_p99 = out["belt"]["p99"]
events_s = 1e9 * lam_p99 / ORBIT_25AU_S
print(f"P5: 1e9 bodies at belt p99 ({lam_p99:.2e}/orbit, orbit {ORBIT_25AU_S:.2e} s): {events_s:.2f} events/game-s")
print(f"    certificate stream at 1e9 (25 events/s at 1e5, birth-stagger ed3a): {25 * 1e4:.1e} events/s")
print(f"    ratio: {25 * 1e4 / events_s:.1e}x")

# P6: the lookahead inequality, both regimes.
for tag, lam, in [("belt p99", out["belt"]["p99"]), ("co-orbital p50", out["coorbital"]["p50"]), ("co-orbital max", out["coorbital"]["max"])]:
    horizon = 11.5 / lam  # ln(1e5): 1e-8 state error grown to phase-accuracy 1e-3
    print(f"P6: {tag}: lambda={lam:.3f}/orbit -> prediction horizon {horizon:8.0f} local orbits "
          f"({horizon * 3.95:.0f} yr at 2.5 AU / {horizon * 11.86:.0f} planet-periods at 5.2 AU)")

# belt hotspots: nearest strong Jovian MMR for the top-5 ICs
res = {f"{p}:{q}": 5.2 * (q / p) ** (2 / 3) for p, q in [(4, 1), (3, 1), (5, 2), (7, 3)]}
top = sorted(rows["belt"], key=lambda r: -lam_local(r, "belt"))[:5]
print("\nbelt top-5 ICs and their nearest strong MMR:")
for r in top:
    near = min(res.items(), key=lambda kv: abs(kv[1] - r["a_au"]))
    print(f"  a={r['a_au']:.3f} phi={r['phi']:3.0f} lambda.Plocal={lam_local(r, 'belt'):.3e} "
          f"nearest {near[0]} at {near[1]:.3f} AU (off by {r['a_au'] - near[1]:+.3f})")

# co-orbital: flat in amplitude? medians per delta bin
co = rows["coorbital"]
bins = {}
for r in co:
    d = min(abs(r["phi"] - 60), abs(r["phi"] - 300)) % 360
    bins.setdefault(int(d // 30), []).append(lam_local(r, "coorbital"))
print("\nco-orbital lambda per planet period by tadpole amplitude bin (deg from L4/L5):")
for k in sorted(bins):
    v = sorted(bins[k])
    print(f"  {k * 30:3d}-{k * 30 + 30:3d}: n={len(v):2d} median={statistics.median(v):.3f} max={v[-1]:.3f}")
